// Entry points and reading share the same mathematical explanations as the experiments.
import {hairyExperiment,surfacesExperiment,banachExperiment} from './lab/experiments/topology.js';
const P=(fr,en)=>[fr,en];
const records=[
 {exp:hairyExperiment,id:'hairy-ball',gallery:'hairy-ball-gallery',card:{intro:P('Des dizaines de milliers de cheveux suivent un champ tangent à la sphère. Peigne-la comme tu veux : il reste toujours un épi, et la somme des indices des épis vaut 2.','Tens of thousands of hairs follow a tangent field on the sphere. Comb it as you like: a cowlick always remains, and the indices of the cowlicks add up to 2.')},figure:'',sources:[['https://warwick.ac.uk/fac/sci/maths/people/staff/peizeliu/ma4j7_2024/ma3_alg_top.pdf',P('Notes de topologie algébrique : degré et théorème de la boule chevelue','Algebraic topology notes: degree and the hairy ball theorem')]],quiz:P('Combien de zéros un champ tangent continu sur S² possède-t-il au minimum ?','What minimum number of zeros must a continuous tangent field on S² have?'),answer:1},
 {exp:surfacesExperiment,id:'nonorientable-surfaces',gallery:'nonorientable-surfaces-gallery',figure:'',sources:[['https://webapps.math.uci.edu/~vmm/Surface/klein_bottle/klein_bottle.html',P('Hermann Karcher : équations de l’immersion en huit','Hermann Karcher: figure-eight immersion equations')],['https://doi.org/10.1080/07468342.2023.2271827',P('Cutting the Möbius Strip, College Mathematics Journal, 2024','Cutting the Möbius Strip, College Mathematics Journal, 2024')]],quiz:P('Combien de composantes du bord possède une bouteille de Klein avant toute coupe ?','How many boundary components does an uncut Klein bottle have?'),answer:0},
 {exp:banachExperiment,id:'banach-tarski',gallery:'banach-tarski-gallery',card:{title:P('Une boule, deux boules','One ball, two balls'),short:P('Le paradoxe de Banach-Tarski','The Banach-Tarski paradox'),intro:P('L’orbite d’un point sous deux rotations se découpe en quatre pièces ; deux d’entre elles, tournées, redonnent toute l’orbite, deux fois. Le calcul est exact, le dessin est fini, le paradoxe vit dans l’infini.','The orbit of a point under two rotations splits into four pieces; turn two of them and the whole orbit comes back, twice. The computation is exact, the drawing is finite, the paradox lives in the infinite.')},figure:'Stefan Banach · Alfred Tarski',sources:[['https://drops.dagstuhl.de/entities/document/10.4230/LIPIcs.ITP.2022.5',P('Bapanapally et Gamboa, preuve mécanisée de Banach-Tarski, 2022','Bapanapally and Gamboa, mechanized proof of Banach-Tarski, 2022')],['https://plato.stanford.edu/entries/axiom-choice/',P('Stanford Encyclopedia of Philosophy : axiome du choix','Stanford Encyclopedia of Philosophy: axiom of choice')]],quiz:P('Peut-on découper une boule en un nombre fini de morceaux puis, en les déplaçant sans les déformer, reconstituer deux boules identiques à la première ?','Can a ball be cut into finitely many pieces which, moved without being stretched, reassemble into two balls identical to the first?'),explain:P('Oui, et c’est un théorème (Banach et Tarski, 1924) : cinq morceaux suffisent. Le paradoxe tient aux morceaux : ce ne sont pas des morceaux qu’on pourrait couper au couteau, mais des nuages de points si dispersés qu’on ne peut leur attribuer aucun volume. Leur existence repose sur l’axiome du choix. Avec des morceaux ordinaires, qui ont un volume, c’est impossible, puisque déplacer ne change pas le volume. Dans l’expérience, un nombre fini de points est déplacé sans copie : leur nombre ne change jamais, le paradoxe ne vit que dans l’infini.','Yes, and it is a theorem (Banach and Tarski, 1924): five pieces suffice. The paradox lies in the pieces: they are not pieces one could cut with a knife, but clouds of points so scattered that no volume can be given to them. Their existence relies on the axiom of choice. With ordinary pieces, which have a volume, it is impossible, since moving does not change volume. In the experiment, finitely many points are moved without copying: their number never changes, the paradox lives only in the infinite.')},
];
// `card` (optional) gives the gallery entry its own title and introduction when the gallery shows a different exhibit than the laboratory (the 3D GPU exhibits).
export const TOPOLOGY_GALLERY=records.map(({exp,gallery,id,sources,quiz,answer,explain,card})=>({id:gallery,custom:true,symbol:exp.symbol,group:exp.group,title:card?.title??exp.title,short:card?.short??exp.short,intro:card?.intro??exp.intro,prereq:exp.prereq,duration:exp.duration,level:exp.level,params:[],formula:'',steps:[exp.intro,exp.conclusion],quiz,answer,explain:explain||exp.conclusion,history:exp.history.title,story:exp.history.story,source:sources[0][0],sourceLabel:sources[0][1],links:[`#lab/${exp.id}`,`#stories/${id}`]}));
export const TOPOLOGY_STORIES=records.map(({exp,id,gallery,figure,sources})=>({id,kind:'lesson',title:exp.title,figure,dek:exp.intro,
 sections:[[P('Ce que l’on observe','What is observed'),[exp.conclusion]],[P('L’argument et ses hypothèses','The argument and its assumptions'),[exp.missions.at(-1).argument]],[P('Voir, puis distinguer','See, then distinguish'),[id==='hairy-ball'?P('Le modèle propose deux champs sur S², tous deux avec deux zéros. Il n’affirme pas que tout champ a exactement deux zéros : un champ nul partout en aurait une infinité. Le théorème impose au moins un zéro. La norme des flèches reste visible ; les normaliser près d’un zéro masquerait la continuité.','The model offers two fields on S², each with two zeros. It does not claim every field has exactly two: the identically zero field has infinitely many. The theorem requires at least one. Arrow lengths remain visible; normalizing near a zero would hide continuity.'):id==='nonorientable-surfaces'?P('Le ruban intact a un bord et n’est pas orientable. Une coupe centrale donne une composante orientable à deux bords. Une coupe au tiers, poursuivie jusqu’à fermeture de la trajectoire, donne une composante de Möbius et un cylindre : trois bords au total. Klein intact a zéro bord. Le couper le long du méridien donne un cylindre. Ces affirmations se vérifient en recollant les bords des rectangles correspondants ; compter les intersections de l’image ne les établit pas.','The uncut strip has one boundary and is nonorientable. A centre cut gives one orientable component with two boundaries. A one-third cut, continued until its path closes, gives a Möbius component and a cylinder: three boundaries in total. Uncut Klein has no boundary. A meridian cut gives a cylinder. These statements follow by gluing the appropriate rectangle edges; counting image intersections does not establish them.'):P('Une partition finie signifie un nombre fini de sous-ensembles, pas des sous-ensembles finis. Le théorème ne contredit pas l’invariance du volume pour des morceaux mesurables. Il montre que l’on ne peut pas attribuer à tous les sous-ensembles de l’espace un volume fini-additif et invariant qui prolonge le volume usuel. Le choix intervient dans une preuve d’existence, et non dans des instructions exécutables sur les points d’un objet matériel.','A finite partition means finitely many subsets, not finite subsets. The theorem does not contradict volume invariance for measurable pieces. It shows that not every subset of space can have a finitely additive invariant volume extending ordinary volume. Choice enters an existence proof, not executable instructions on the points of a physical object.')]]],
 links:[`#lab/${exp.id}`,`#gallery/${gallery}`],sources}));
